CREATE OR REPLACE FUNCTION private.basic_set_client_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT private.basic_is_coach() THEN RAISE EXCEPTION 'Verified coach required' USING ERRCODE='42501'; END IF;
  IF new.coach_id IS NOT NULL AND new.coach_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Cannot create a client for another coach' USING ERRCODE='42501';
  END IF;
  new.coach_id := auth.uid();
  RETURN new;
END;$function$

CREATE OR REPLACE FUNCTION private.guard_client_data()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE old_safe jsonb; new_safe jsonb;
        old_coach jsonb; new_coach jsonb; rec jsonb;
        new_records jsonb;
BEGIN
 IF NOT private.can_manage_client(old.id) THEN
  IF new.email IS DISTINCT FROM old.email OR new.id IS DISTINCT FROM old.id THEN
    RAISE EXCEPTION 'Client identity is coach-owned' USING ERRCODE='42501';
  END IF;
  old_safe := old.data - 'photoUrl' - 'nutrition' - 'manualRecords';
  new_safe := new.data - 'photoUrl' - 'nutrition' - 'manualRecords';
  IF old_safe IS DISTINCT FROM new_safe OR
    (coalesce(old.data->'nutrition','{}'::jsonb) - 'log') IS DISTINCT FROM
    (coalesce(new.data->'nutrition','{}'::jsonb) - 'log') THEN
   RAISE EXCEPTION 'Coach-owned profile or assessment cannot be changed' USING ERRCODE='42501';
  END IF;
  IF (new.data ? 'manualRecords') AND
     jsonb_typeof(new.data->'manualRecords') <> 'array' THEN
   RAISE EXCEPTION 'Invalid manual records' USING ERRCODE='22023';
  END IF;
  new_records := CASE WHEN jsonb_typeof(new.data->'manualRecords')='array'
                      THEN new.data->'manualRecords' ELSE '[]'::jsonb END;
  IF jsonb_array_length(new_records) > 500 THEN
   RAISE EXCEPTION 'Too many manual records' USING ERRCODE='22023';
  END IF;
  -- Coach-created records must survive unchanged, including attribution and IDs.
  SELECT coalesce(jsonb_agg(r.value ORDER BY r.value->>'id'),'[]'::jsonb)
   INTO old_coach FROM jsonb_array_elements(
    CASE WHEN jsonb_typeof(old.data->'manualRecords')='array'
         THEN old.data->'manualRecords' ELSE '[]'::jsonb END) r
   WHERE r.value->>'addedBy' IS DISTINCT FROM 'client';
  SELECT coalesce(jsonb_agg(r.value ORDER BY r.value->>'id'),'[]'::jsonb)
   INTO new_coach FROM jsonb_array_elements(new_records) r
   WHERE r.value->>'addedBy' IS DISTINCT FROM 'client';
  IF old_coach IS DISTINCT FROM new_coach THEN
   RAISE EXCEPTION 'Coach-created records cannot be edited or deleted' USING ERRCODE='42501';
  END IF;
  -- No duplicate IDs or malformed client records (prevents collisions with coach IDs).
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(new_records) r
    WHERE jsonb_typeof(r.value) <> 'object' OR nullif(r.value->>'id','') IS NULL
       OR length(r.value->>'id') > 120) OR
     (SELECT count(*) FROM jsonb_array_elements(new_records)) <>
     (SELECT count(DISTINCT r.value->>'id') FROM jsonb_array_elements(new_records) r) THEN
   RAISE EXCEPTION 'Invalid or duplicate manual record IDs' USING ERRCODE='22023';
  END IF;
  FOR rec IN SELECT value FROM jsonb_array_elements(new_records)
    WHERE value->>'addedBy'='client' LOOP
   IF (rec - 'id' - 'exerciseId' - 'name' - 'kg' - 'reps' - 'date' - 'note' - 'addedBy') <> '{}'::jsonb
      OR jsonb_typeof(rec->'name') <> 'string' OR length(trim(rec->>'name')) NOT BETWEEN 1 AND 200
      OR jsonb_typeof(rec->'kg') <> 'number' OR (rec->>'kg')::numeric NOT BETWEEN 0 AND 10000
      OR jsonb_typeof(rec->'reps') <> 'number' OR (rec->>'reps')::numeric NOT BETWEEN 1 AND 100
      OR (rec->>'reps')::numeric <> trunc((rec->>'reps')::numeric)
      OR (rec ? 'date' AND (jsonb_typeof(rec->'date') <> 'string' OR rec->>'date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'))
      OR (rec ? 'note' AND (jsonb_typeof(rec->'note') <> 'string' OR length(rec->>'note') > 2000))
      OR (rec ? 'exerciseId' AND (jsonb_typeof(rec->'exerciseId') <> 'string' OR length(rec->>'exerciseId') > 200)) THEN
    RAISE EXCEPTION 'Invalid client manual record' USING ERRCODE='22023';
   END IF;
  END LOOP;
 END IF;
 RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION private.guard_client_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_coach() and new.email is distinct from old.email then
    raise exception 'Only the coach can change a client''s email';
  end if;
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_coach_message_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.body is distinct from old.body or new.client_id is distinct from old.client_id
     or new.from_coach is distinct from old.from_coach or new.attachment_path is distinct from old.attachment_path then
    raise exception 'Messages cannot be edited';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.guard_message_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.body is distinct from old.body or new.sender is distinct from old.sender
     or new.client_id is distinct from old.client_id or new.created_at is distinct from old.created_at then
    raise exception 'Messages can''t be edited';
  end if;
  if new.read_at is distinct from old.read_at
     and ((old.sender = 'coach') = private.is_coach()) then
    raise exception 'Only the receiver marks a message read';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.link_user(uid uuid, user_email text, user_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE cid text; cname text;
BEGIN
 IF EXISTS (SELECT 1 FROM public.profiles WHERE id=uid) THEN RETURN; END IF;
 IF EXISTS (SELECT 1 FROM private.coach_allowlist a WHERE a.email=lower(user_email)) THEN
   INSERT INTO public.profiles(id,role,display_name)
     VALUES(uid,'coach',coalesce(nullif(user_name,''),split_part(user_email,'@',1)));
   RETURN;
 END IF;
 SELECT c.id,c.data->>'name' INTO cid,cname FROM public.clients c
 WHERE lower(c.email)=lower(user_email) LIMIT 1;
 IF cid IS NOT NULL THEN
   INSERT INTO public.profiles(id,role,display_name,client_id)
     VALUES(uid,'client',coalesce(cname,split_part(user_email,'@',1)),cid);
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION private.on_client_email_set()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  u record;
begin
  if new.email <> '' then
    for u in select id, email from auth.users where private.email_key(email) = private.email_key(new.email) loop
      perform private.link_user(u.id, u.email, null);
    end loop;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.reject_inline_notes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF new.data ? 'coachNotes' THEN
  RAISE EXCEPTION 'Use coach_notes_secure; inline notes are forbidden' USING ERRCODE='42501';
 END IF;
 RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION private.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.my_referral_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  cid text := private.my_client_id();
  c text;
begin
  if cid is null then
    return null;
  end if;
  select code into c from public.referral_codes where client_id = cid;
  if c is null then
    loop
      c := lower(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
      begin
        insert into public.referral_codes (client_id, code) values (cid, c);
        exit;
      exception when unique_violation then
      end;
    end loop;
  end if;
  return c;
end;
$function$

CREATE OR REPLACE FUNCTION public.pf_manage_trainer(p_action text, p_email text, p_client_id text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE addr text:=lower(trim(p_email));
BEGIN
  IF NOT public.pf_head_coach() THEN RAISE EXCEPTION 'Head coach only' USING ERRCODE='42501'; END IF;
  IF p_action IS DISTINCT FROM 'invite' THEN
    RAISE EXCEPTION 'Client assignments are automatic and cannot be transferred' USING ERRCODE='42501';
  END IF;
  IF addr !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(addr)>254 THEN
    RAISE EXCEPTION 'Invalid email' USING ERRCODE='22023';
  END IF;
  INSERT INTO private.coach_allowlist(email) VALUES(addr) ON CONFLICT DO NOTHING;
  RETURN true;
END;$function$

CREATE OR REPLACE FUNCTION public.pf_publish_posture_review(p_client_id text, p_assessment_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE doc jsonb; clean jsonb; chosen jsonb;
BEGIN
 IF NOT private.can_manage_client(p_client_id) THEN RAISE EXCEPTION 'Not assigned' USING ERRCODE='42501'; END IF;
 IF p_assessment_id IS NULL OR p_assessment_id NOT LIKE 'as-%' OR NOT EXISTS (
   SELECT 1 FROM public.clients c, jsonb_array_elements(coalesce(c.data->'assessments','[]'::jsonb)) a
   WHERE c.id=p_client_id AND a->>'id'=p_assessment_id) THEN
   RAISE EXCEPTION 'Save dated assessment first'; END IF;
 SELECT data INTO doc FROM public.posture_reviews_secure WHERE client_id=p_client_id AND assessment_id='draft';
 IF doc IS NULL OR doc->>'summaryApprovedByCoach' <> 'true' OR trim(coalesce(doc->>'summary',''))='' THEN
  RAISE EXCEPTION 'Coach-approved summary required'; END IF;
 INSERT INTO public.posture_reviews_secure(client_id,assessment_id,data)
 VALUES(p_client_id,p_assessment_id,doc) ON CONFLICT DO NOTHING;
 SELECT data INTO chosen FROM public.posture_reviews_secure WHERE client_id=p_client_id AND assessment_id=p_assessment_id;
 IF chosen->>'summaryApprovedByCoach' <> 'true' THEN RAISE EXCEPTION 'Historical snapshot is not approved'; END IF;
 -- Explicit client whitelist. NEVER include private interpretation, conflicts, reviewer notes, rule internals.
 SELECT coalesce(jsonb_agg(o),'[]'::jsonb) INTO clean FROM jsonb_array_elements(coalesce(chosen->'observations','[]'::jsonb)) o
 WHERE o->>'confirmed'='true';
 INSERT INTO public.posture_public_reports(client_id,assessment_id,data)
 VALUES(p_client_id,p_assessment_id,jsonb_build_object(
  'recordedAt',chosen->>'recordedAt','measurements',coalesce(chosen->'measurements','[]'::jsonb),
  'observations',clean,'summary',chosen->>'summary','summaryApprovedByCoach',true,
  'visualSettings',coalesce(chosen->'visualSettings','{}'::jsonb))) ON CONFLICT DO NOTHING;
 RETURN true;
END;$function$

CREATE OR REPLACE FUNCTION public.pf_save_food_entry(p_client_id text, p_existing_id uuid, p_date date, p_description text, p_key uuid, p_status text, p_items jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE eid uuid; item jsonb;
BEGIN
 IF auth.uid() IS NULL OR p_client_id IS DISTINCT FROM private.my_client_id() THEN
  RAISE EXCEPTION 'Own food records only' USING ERRCODE='42501'; END IF;
 IF p_date IS NULL OR p_date > current_date + 1 OR p_description IS NULL OR length(trim(p_description)) NOT BETWEEN 1 AND 2000 THEN
  RAISE EXCEPTION 'Invalid entry' USING ERRCODE='22023'; END IF;
 IF p_status NOT IN ('estimate','confirmed','incomplete') OR jsonb_typeof(p_items)<>'array' OR
   jsonb_array_length(p_items) NOT BETWEEN 1 AND 30 THEN RAISE EXCEPTION 'Invalid meal items'; END IF;
 IF p_existing_id IS NOT NULL THEN
   SELECT id INTO eid FROM public.food_entries WHERE id=p_existing_id AND client_id=p_client_id FOR UPDATE;
   IF eid IS NULL THEN RAISE EXCEPTION 'Meal not found or access denied' USING ERRCODE='42501'; END IF;
 ELSE
   SELECT id INTO eid FROM public.food_entries WHERE client_id=p_client_id AND idempotency_key=p_key FOR UPDATE;
 END IF;
 IF eid IS NULL THEN
   INSERT INTO public.food_entries(client_id,date,description,idempotency_key,status)
     VALUES(p_client_id,p_date,trim(p_description),p_key,p_status) RETURNING id INTO eid;
 ELSE
   UPDATE public.food_entries SET date=p_date,description=trim(p_description),status=p_status WHERE id=eid;
 END IF;
 DELETE FROM public.food_items WHERE entry_id=eid AND client_id=p_client_id;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
   IF length(trim(coalesce(item->>'name',''))) NOT BETWEEN 1 AND 200
      OR coalesce((item->>'quantity')::numeric,0) <= 0 THEN RAISE EXCEPTION 'Invalid food'; END IF;
   INSERT INTO public.food_items(entry_id,client_id,name,quantity,unit,grams,state,kcal,protein,source,"sourceId",assumptions,version,"kcalPerGram","proteinPerGram")
   VALUES(eid,p_client_id,trim(item->>'name'),(item->>'quantity')::numeric,item->>'unit',
     NULLIF(item->>'grams','')::numeric,coalesce(item->>'state','unknown'),
     NULLIF(item->>'kcal','')::numeric,NULLIF(item->>'protein','')::numeric,
     coalesce(item->>'source','manual'),item->>'sourceId',coalesce(item->>'assumptions',''),
     coalesce(item->>'version','food-v1'),NULLIF(item->>'kcalPerGram','')::numeric,NULLIF(item->>'proteinPerGram','')::numeric);
 END LOOP;
 RETURN eid;
END;$function$

CREATE OR REPLACE FUNCTION public.reserve_signup_verification(p_email text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  addr text := lower(trim(p_email));
  digest text;
  recent timestamptz[];
BEGIN
  IF addr IS NULL OR char_length(addr) > 254 OR addr !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RETURN false;
  END IF;
  -- Even a service-role call must not create a link for missing/confirmed accounts.
  IF NOT EXISTS (
    SELECT 1 FROM auth.users u
    WHERE lower(u.email) = addr AND u.email_confirmed_at IS NULL
  ) THEN RETURN false; END IF;
  digest := encode(pg_catalog.sha256(pg_catalog.convert_to(addr, 'UTF8')), 'hex');
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(digest, 0));
  SELECT coalesce(array_agg(t) FILTER (WHERE t > now() - interval '1 hour'), ARRAY[]::timestamptz[])
    INTO recent
    FROM public.signup_verification_resends s,
         unnest(s.attempts) AS t
   WHERE s.email_digest = digest;
  recent := coalesce(recent, ARRAY[]::timestamptz[]);
  IF coalesce(array_length(recent, 1), 0) >= 3 THEN RETURN false; END IF;
  INSERT INTO public.signup_verification_resends (email_digest, attempts)
    VALUES (digest, array_append(recent, now()))
    ON CONFLICT (email_digest) DO UPDATE SET attempts = excluded.attempts;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_workout_results_secure(p_workout_id text, p_client_id text, p_expected_version timestamp with time zone, p_results jsonb)
 RETURNS TABLE(updated_version timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w public.workouts%ROWTYPE; b jsonb; patch jsonb; next_blocks jsonb := '[]'::jsonb;
        touched jsonb := '[]'::jsonb; current_ids text[]; wanted_ids text[];
BEGIN
 IF auth.uid() IS NULL OR p_client_id IS DISTINCT FROM private.my_client_id() THEN
  RAISE EXCEPTION 'Not your client' USING ERRCODE='42501'; END IF;
 SELECT * INTO w FROM public.workouts WHERE id=p_workout_id AND client_id=p_client_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Workout not found' USING ERRCODE='42501'; END IF;
 IF w.updated_at IS DISTINCT FROM p_expected_version THEN
  RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001'; END IF;
 IF jsonb_typeof(p_results) IS DISTINCT FROM 'object' OR
    (p_results - 'blocks' - 'status' - 'completedAt' - 'sessionRpe' - 'clientFeedback') <> '{}'::jsonb THEN
   RAISE EXCEPTION 'Invalid result fields' USING ERRCODE='42501'; END IF;
 IF NOT (p_results ? 'status') OR NOT (p_results ? 'blocks') THEN
   RAISE EXCEPTION 'Missing required results' USING ERRCODE='22023'; END IF;
 IF (p_results ? 'clientFeedback') AND p_results->'clientFeedback' <> 'null'::jsonb AND
   (jsonb_typeof(p_results->'clientFeedback') IS DISTINCT FROM 'string' OR
    length(p_results->>'clientFeedback') > 4000) THEN
   RAISE EXCEPTION 'Invalid feedback' USING ERRCODE='22023'; END IF;
 IF (p_results ? 'completedAt') AND p_results->'completedAt' <> 'null'::jsonb AND
    jsonb_typeof(p_results->'completedAt') IS DISTINCT FROM 'string' THEN
   RAISE EXCEPTION 'Invalid completion date' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p_results->'blocks') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION 'Blocks must be an array' USING ERRCODE='22023'; END IF;
 IF (p_results ? 'status') AND (p_results->>'status') NOT IN ('planned','completed','missed') THEN
   RAISE EXCEPTION 'Invalid status' USING ERRCODE='22023'; END IF;
 IF (p_results ? 'sessionRpe') AND p_results->'sessionRpe' <> 'null'::jsonb AND
    (jsonb_typeof(p_results->'sessionRpe') <> 'number' OR (p_results->>'sessionRpe')::numeric NOT BETWEEN 1 AND 10) THEN
   RAISE EXCEPTION 'Invalid RPE' USING ERRCODE='22023'; END IF;
 SELECT array_agg(e->>'id' ORDER BY e->>'id') INTO current_ids FROM jsonb_array_elements(w.data->'blocks') e;
 SELECT array_agg(e->>'id' ORDER BY e->>'id') INTO wanted_ids FROM jsonb_array_elements(p_results->'blocks') e;
 IF current_ids IS DISTINCT FROM wanted_ids THEN
   RAISE EXCEPTION 'Block ids mismatch' USING ERRCODE='42501'; END IF;
 FOR b IN SELECT value FROM jsonb_array_elements(w.data->'blocks') LOOP
   SELECT value INTO patch FROM jsonb_array_elements(p_results->'blocks') WHERE value->>'id'=b->>'id';
   IF jsonb_typeof(patch) <> 'object' OR
      (patch - 'id' - 'loggedSets' - 'rpe' - 'pain' - 'clientNote') <> '{}'::jsonb THEN
     RAISE EXCEPTION 'Only client result fields allowed' USING ERRCODE='42501'; END IF;
   IF NOT (patch ? 'loggedSets') OR jsonb_typeof(patch->'loggedSets') <> 'array' OR
     jsonb_array_length(patch->'loggedSets') <> jsonb_array_length(b->'loggedSets') THEN
     RAISE EXCEPTION 'Set shape changed' USING ERRCODE='42501'; END IF;
   -- All prescribed set numbers must match, and each set has only the logging fields.
   IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(patch->'loggedSets') s
    WHERE (s.value - 'setNumber' - 'kg' - 'reps' - 'completed') <> '{}'::jsonb
       OR NOT EXISTS (SELECT 1 FROM jsonb_array_elements(b->'loggedSets') orig
                      WHERE orig->'setNumber'=s.value->'setNumber')
   ) THEN RAISE EXCEPTION 'Invalid set result' USING ERRCODE='42501'; END IF;
   IF EXISTS (
     SELECT 1 FROM jsonb_array_elements(patch->'loggedSets') item
     WHERE NOT (item.value ? 'setNumber') OR NOT (item.value ? 'kg') OR
           NOT (item.value ? 'reps') OR NOT (item.value ? 'completed') OR
           jsonb_typeof(item.value->'completed') IS DISTINCT FROM 'boolean'
       OR jsonb_typeof(item.value->'setNumber') IS DISTINCT FROM 'number'
       OR (item.value->'kg' <> 'null'::jsonb AND
          (jsonb_typeof(item.value->'kg') IS DISTINCT FROM 'number' OR
           (item.value->>'kg')::numeric NOT BETWEEN 0 AND 100000))
       OR (item.value->'reps' <> 'null'::jsonb AND
          (jsonb_typeof(item.value->'reps') IS DISTINCT FROM 'number' OR
           (item.value->>'reps')::numeric NOT BETWEEN 0 AND 100000))
   ) THEN RAISE EXCEPTION 'Invalid result values' USING ERRCODE='22023'; END IF;
   IF (patch ? 'rpe') AND patch->'rpe' <> 'null'::jsonb AND
      (jsonb_typeof(patch->'rpe') IS DISTINCT FROM 'number' OR
       (patch->>'rpe')::numeric NOT BETWEEN 0 AND 10) THEN
     RAISE EXCEPTION 'Invalid exercise RPE' USING ERRCODE='22023'; END IF;
   IF (patch ? 'clientNote') AND patch->'clientNote' <> 'null'::jsonb AND
      (jsonb_typeof(patch->'clientNote') IS DISTINCT FROM 'string' OR
       length(patch->>'clientNote') > 4000) THEN
     RAISE EXCEPTION 'Invalid client note' USING ERRCODE='22023'; END IF;
   IF (patch ? 'pain') AND jsonb_typeof(patch->'pain') IS DISTINCT FROM 'boolean' THEN
     RAISE EXCEPTION 'Invalid pain field' USING ERRCODE='22023'; END IF;
   b := (b - 'loggedSets' - 'rpe' - 'pain' - 'clientNote') ||
      (patch - 'id');
   next_blocks := next_blocks || jsonb_build_array(b);
 END LOOP;
 UPDATE public.workouts SET data = (w.data - 'blocks' - 'status' - 'completedAt' - 'sessionRpe' - 'clientFeedback') ||
   (p_results - 'blocks') || jsonb_build_object('blocks',next_blocks), updated_at=clock_timestamp()
 WHERE id=w.id RETURNING updated_at INTO updated_version;
 RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_referral_status(p_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE amount numeric; cid text;
BEGIN
 SELECT referrer_client_id INTO cid FROM public.referrals WHERE id=p_id;
 IF cid IS NULL OR NOT private.can_manage_client(cid) THEN
  RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
 IF p_status NOT IN ('invited','signed_up','paying','declined') THEN
  RAISE EXCEPTION 'Unknown status' USING ERRCODE='22023'; END IF;
 SELECT coalesce(nullif(value,'')::numeric,0) INTO amount FROM private.settings WHERE key='referral_credit';
 UPDATE public.referrals SET status=p_status,
  credit=CASE WHEN p_status='paying' THEN CASE WHEN credit>0 THEN credit ELSE coalesce(amount,0) END ELSE 0 END,
  updated_at=now() WHERE id=p_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_referral(p_code text, p_name text, p_email text, p_location text, p_note text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  cid text;
  e text := lower(trim(p_email));
begin
  select client_id into cid from public.referral_codes where code = lower(trim(p_code));
  if cid is null then
    raise exception 'Invalid invite link';
  end if;
  if e !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'Please enter a valid email';
  end if;
  if (select count(*) from public.referrals where referrer_client_id = cid and created_at > now() - interval '1 day') >= 20 then
    raise exception 'Too many invites today, please try again tomorrow';
  end if;
  insert into public.referrals (referrer_client_id, name, email, location, note)
  values (cid, left(trim(p_name), 120), e, left(trim(coalesce(p_location, '')), 120), left(trim(coalesce(p_note, '')), 1000))
  on conflict (referrer_client_id, lower(email)) do nothing;
  return true;
end;
$function$
